<?php
if (!defined('ABSPATH')) { exit; }
/** Caisse, taux de change et rapports financiers. */
final class FKC_Finance_API {
 private static function t($n){global $wpdb;return in_array($n,array('users','tenants','branches','members','permissions','branch_access','invitations','audit_logs','sessions'),true)?'bta_'.$n:$wpdb->prefix.'bta_'.$n;}
 private static function err($c,$m,$s=400){return new WP_Error($c,$m,array('status'=>$s));}
 private static function auth($r,$tenant,$perm){$h=$r->get_header('authorization');if(!$h&&isset($_SERVER['HTTP_AUTHORIZATION']))$h=wp_unslash($_SERVER['HTTP_AUTHORIZATION']);if(!is_string($h)||!preg_match('/^Bearer\s+([a-fA-F0-9]{64})$/',$h,$m))return self::err('bta_unauthenticated','Connexion requise.',401);global $wpdb;$s=$wpdb->get_row($wpdb->prepare('SELECT s.user_id,u.status FROM '.self::t('sessions').' s JOIN '.self::t('users').' u ON u.id=s.user_id WHERE s.token_hash=%s AND s.expires_at>%s LIMIT 1',hash('sha256',$m[1]),gmdate('Y-m-d H:i:s')),ARRAY_A);if(!$s||$s['status']!=='ACTIVE')return self::err('bta_unauthenticated','Session invalide ou expirée.',401);$mem=$wpdb->get_row($wpdb->prepare("SELECT role FROM ".self::t('members')." WHERE tenant_id=%d AND user_id=%d AND status='ACTIVE' LIMIT 1",$tenant,$s['user_id']),ARRAY_A);if(!$mem)return self::err('bta_forbidden','Accès refusé.',403);$map=array('OWNER'=>array('cashbox.manage','reports.read'),'ADMIN'=>array('cashbox.manage','reports.read'),'MANAGER'=>array('cashbox.manage','reports.read'),'CASHIER'=>array('cashbox.manage'));if(!in_array($perm,$map[$mem['role']]??array(),true))return self::err('bta_forbidden','Permission insuffisante.',403);return array('user_id'=>(int)$s['user_id']);}
 public static function boot(){add_action('rest_api_init',array(__CLASS__,'routes'));}
 public static function routes(){
 register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/cash/sessions',array(array('methods'=>'GET','callback'=>array(__CLASS__,'sessions'),'permission_callback'=>'__return_true'),array('methods'=>'POST','callback'=>array(__CLASS__,'open_session'),'permission_callback'=>'__return_true')));
 register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/cash/sessions/(?P<session_id>\d+)/close',array('methods'=>'POST','callback'=>array(__CLASS__,'close_session'),'permission_callback'=>'__return_true'));
 register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/cash/sessions/(?P<session_id>\d+)/movements',array('methods'=>'POST','callback'=>array(__CLASS__,'movement'),'permission_callback'=>'__return_true'));
 register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/exchange-rates',array(array('methods'=>'GET','callback'=>array(__CLASS__,'rates'),'permission_callback'=>'__return_true'),array('methods'=>'POST','callback'=>array(__CLASS__,'rate_create'),'permission_callback'=>'__return_true')));
 register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/reports/summary',array('methods'=>'GET','callback'=>array(__CLASS__,'summary'),'permission_callback'=>'__return_true'));
 register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/reports/profitability',array('methods'=>'GET','callback'=>array(__CLASS__,'profitability'),'permission_callback'=>'__return_true'));
 register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/reports/stock-valuation',array('methods'=>'GET','callback'=>array(__CLASS__,'stock_valuation'),'permission_callback'=>'__return_true'));
 }
 public static function sessions($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'cashbox.manage');if(is_wp_error($a))return $a;global $wpdb;$b=absint($r->get_param('branch_id'));$sql='SELECT id,branch_id,user_id,opening_amount,closing_amount,currency,status,opened_at,closed_at FROM '.self::t('cash_sessions').' WHERE tenant_id=%d';$args=array($t);if($b){$sql.=' AND branch_id=%d';$args[]=$b;}$sql.=' ORDER BY id DESC LIMIT 100';$rows=$wpdb->get_results($wpdb->prepare($sql,$args),ARRAY_A);return array('success'=>true,'sessions'=>$rows);}
 public static function open_session($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'cashbox.manage');if(is_wp_error($a))return $a;$b=absint($r->get_param('branch_id'));$cur=strtoupper((string)($r->get_param('currency')?:'USD'));$opening=(float)$r->get_param('opening_amount');if(!$b||$opening<0||!in_array($cur,array('USD','CDF'),true))return self::err('bta_invalid_cash_session','Établissement, devise ou solde initial invalide.');global $wpdb;if(!$wpdb->get_var($wpdb->prepare("SELECT id FROM ".self::t('branches')." WHERE id=%d AND tenant_id=%d AND status='ACTIVE'",$b,$t)))return self::err('bta_invalid_branch','Établissement introuvable.',404);$exists=$wpdb->get_var($wpdb->prepare("SELECT id FROM ".self::t('cash_sessions')." WHERE tenant_id=%d AND branch_id=%d AND user_id=%d AND status='OPEN' LIMIT 1",$t,$b,$a['user_id']));if($exists)return self::err('bta_cash_already_open','Une caisse est déjà ouverte pour cet utilisateur.',409);$now=gmdate('Y-m-d H:i:s');if(!$wpdb->insert(self::t('cash_sessions'),array('tenant_id'=>$t,'branch_id'=>$b,'user_id'=>$a['user_id'],'opening_amount'=>$opening,'currency'=>$cur,'status'=>'OPEN','opened_at'=>$now)))return self::err('bta_cash_open_failed','Ouverture impossible.',500);$id=(int)$wpdb->insert_id;if($opening>0)$wpdb->insert(self::t('cash_movements'),array('tenant_id'=>$t,'cash_session_id'=>$id,'movement_type'=>'OPENING','amount'=>$opening,'currency'=>$cur,'description'=>'Solde initial','created_by'=>$a['user_id'],'created_at'=>$now));return new WP_REST_Response(array('success'=>true,'session_id'=>$id,'status'=>'OPEN'),201);}
 public static function movement($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'cashbox.manage');if(is_wp_error($a))return $a;$id=(int)$r['session_id'];$type=strtoupper(sanitize_key((string)$r->get_param('movement_type')));$amount=(float)$r->get_param('amount');if(!in_array($type,array('CASH_IN','CASH_OUT'),true)||$amount<=0)return self::err('bta_invalid_cash_movement','Type ou montant invalide.');global $wpdb;$s=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::t('cash_sessions')." WHERE id=%d AND tenant_id=%d AND user_id=%d AND status='OPEN'",$id,$t,$a['user_id']),ARRAY_A);if(!$s)return self::err('bta_cash_session_not_found','Caisse ouverte introuvable.',404);$ok=$wpdb->insert(self::t('cash_movements'),array('tenant_id'=>$t,'cash_session_id'=>$id,'movement_type'=>$type,'amount'=>$amount,'currency'=>$s['currency'],'description'=>sanitize_textarea_field((string)$r->get_param('description')),'created_by'=>$a['user_id'],'created_at'=>gmdate('Y-m-d H:i:s')));if(!$ok)return self::err('bta_cash_movement_failed','Mouvement non enregistré.',500);return new WP_REST_Response(array('success'=>true,'movement_id'=>(int)$wpdb->insert_id),201);}
 public static function close_session($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'cashbox.manage');if(is_wp_error($a))return $a;$id=(int)$r['session_id'];$count=$r->get_param('closing_amount');if(!is_numeric($count)||$count<0)return self::err('bta_invalid_closing_amount','Montant de clôture invalide.');global $wpdb;$s=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::t('cash_sessions')." WHERE id=%d AND tenant_id=%d AND user_id=%d AND status='OPEN' FOR UPDATE",$id,$t,$a['user_id']),ARRAY_A);if(!$s)return self::err('bta_cash_session_not_found','Caisse ouverte introuvable.',404);$now=gmdate('Y-m-d H:i:s');$ok=$wpdb->update(self::t('cash_sessions'),array('closing_amount'=>(float)$count,'status'=>'CLOSED','closed_at'=>$now),array('id'=>$id,'tenant_id'=>$t,'status'=>'OPEN'));if($ok===false)return self::err('bta_cash_close_failed','Clôture impossible.',500);$sum=(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(CASE WHEN movement_type IN ('OPENING','CASH_IN','SALE_IN','DEBT_IN') THEN amount WHEN movement_type IN ('CASH_OUT','EXPENSE_OUT') THEN -amount ELSE 0 END),0) FROM ".self::t('cash_movements')." WHERE tenant_id=%d AND cash_session_id=%d",$t,$id));return array('success'=>true,'session_id'=>$id,'status'=>'CLOSED','expected_amount'=>$sum,'counted_amount'=>(float)$count,'difference'=>(float)$count-$sum);}
 public static function rates($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'reports.read');if(is_wp_error($a))return $a;global $wpdb;$rows=$wpdb->get_results($wpdb->prepare('SELECT id,from_currency,to_currency,rate,effective_at,created_at FROM '.self::t('exchange_rates').' WHERE tenant_id=%d ORDER BY effective_at DESC,id DESC LIMIT 100',$t),ARRAY_A);return array('success'=>true,'rates'=>$rows);}
 public static function rate_create($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'cashbox.manage');if(is_wp_error($a))return $a;$from=strtoupper((string)$r->get_param('from_currency'));$to=strtoupper((string)$r->get_param('to_currency'));$rate=(float)$r->get_param('rate');if(!in_array($from,array('USD','CDF'),true)||!in_array($to,array('USD','CDF'),true)||$from===$to||$rate<=0)return self::err('bta_invalid_exchange_rate','Paire de devises ou taux invalide.');global $wpdb;$at=sanitize_text_field((string)($r->get_param('effective_at')?:gmdate('Y-m-d H:i:s')));$dt=date_create($at);if(!$dt)return self::err('bta_invalid_effective_at','Date d’effet invalide.');$now=gmdate('Y-m-d H:i:s');if(!$wpdb->insert(self::t('exchange_rates'),array('tenant_id'=>$t,'from_currency'=>$from,'to_currency'=>$to,'rate'=>$rate,'effective_at'=>$dt->format('Y-m-d H:i:s'),'created_by'=>$a['user_id'],'created_at'=>$now)))return self::err('bta_rate_create_failed','Taux non enregistré.',500);return new WP_REST_Response(array('success'=>true,'rate_id'=>(int)$wpdb->insert_id,'from_currency'=>$from,'to_currency'=>$to,'rate'=>$rate),201);}
 public static function summary($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'reports.read');if(is_wp_error($a))return $a;$from=sanitize_text_field((string)($r->get_param('from')?:gmdate('Y-m-01 00:00:00')));$to=sanitize_text_field((string)($r->get_param('to')?:gmdate('Y-m-d 23:59:59')));$df=date_create($from);$dt=date_create($to);if(!$df||!$dt||$df>$dt)return self::err('bta_invalid_report_period','Période invalide.');$branch=absint($r->get_param('branch_id'));global $wpdb;$sales=self::t('sales');$expenses=self::t('expenses');$purchases=self::t('purchases');$data=array();foreach(array('USD','CDF') as $cur){$data[$cur]=array();foreach(array('sales'=>'total','expenses'=>'amount','purchases'=>'total') as $name=>$column){$table=$name==='sales'?$sales:($name==='expenses'?$expenses:$purchases);$sql="SELECT COALESCE(SUM({$column}),0) FROM {$table} WHERE tenant_id=%d AND currency=%s AND created_at BETWEEN %s AND %s";$args=array($t,$cur,$df->format('Y-m-d H:i:s'),$dt->format('Y-m-d H:i:s'));if($name==='sales')$sql.=" AND status='COMPLETED'";if($branch){$sql.=' AND branch_id=%d';$args[]=$branch;}$data[$cur][$name]=(float)$wpdb->get_var($wpdb->prepare($sql,$args));}}return array('success'=>true,'period'=>array('from'=>$df->format('Y-m-d H:i:s'),'to'=>$dt->format('Y-m-d H:i:s')),'branch_id'=>$branch,'totals'=>$data,'note'=>'Totaux séparés par devise, sans conversion implicite.');}

 public static function profitability($r){
  $t=(int)$r['tenant_id'];$a=self::auth($r,$t,'reports.read');if(is_wp_error($a))return $a;
  $from=sanitize_text_field((string)($r->get_param('from')?:gmdate('Y-m-01 00:00:00')));$to=sanitize_text_field((string)($r->get_param('to')?:gmdate('Y-m-d 23:59:59')));$df=date_create($from);$dt=date_create($to);if(!$df||!$dt||$df>$dt)return self::err('bta_invalid_report_period','Période invalide.');
  $branch=absint($r->get_param('branch_id'));global $wpdb;$out=array();
  foreach(array('USD','CDF') as $cur){$sql="SELECT COALESCE(SUM(si.line_total),0) revenue,COALESCE(SUM(si.quantity*si.unit_cost),0) cost,COUNT(DISTINCT s.id) sales_count FROM ".self::t('sales')." s INNER JOIN ".self::t('sale_items')." si ON si.sale_id=s.id AND si.tenant_id=s.tenant_id WHERE s.tenant_id=%d AND s.currency=%s AND s.status='COMPLETED' AND s.created_at BETWEEN %s AND %s";$args=array($t,$cur,$df->format('Y-m-d H:i:s'),$dt->format('Y-m-d H:i:s'));if($branch){$sql.=' AND s.branch_id=%d';$args[]=$branch;}$row=$wpdb->get_row($wpdb->prepare($sql,$args),ARRAY_A);$revenue=(float)$row['revenue'];$cost=(float)$row['cost'];$out[$cur]=array('sales_count'=>(int)$row['sales_count'],'revenue'=>$revenue,'cost_of_goods_sold'=>$cost,'gross_profit'=>$revenue-$cost,'margin_percent'=>$revenue>0?round((($revenue-$cost)/$revenue)*100,2):0);}
  return array('success'=>true,'period'=>array('from'=>$df->format('Y-m-d H:i:s'),'to'=>$dt->format('Y-m-d H:i:s')),'branch_id'=>$branch?:null,'currencies'=>$out,'note'=>'Le coût des ventes repose sur le coût unitaire enregistré sur chaque ligne de vente; les ventes sans coût renseigné peuvent sous-estimer le coût réel.');
 }
 public static function stock_valuation($r){
  $t=(int)$r['tenant_id'];$a=self::auth($r,$t,'reports.read');if(is_wp_error($a))return $a;$branch=absint($r->get_param('branch_id'));global $wpdb;$sql="SELECT p.currency,COUNT(*) product_lines,COALESCE(SUM(st.quantity),0) total_quantity,COALESCE(SUM(st.quantity*p.purchase_price),0) stock_value FROM ".self::t('stock')." st INNER JOIN ".self::t('products')." p ON p.id=st.product_id AND p.tenant_id=st.tenant_id WHERE st.tenant_id=%d";$args=array($t);if($branch){$sql.=' AND st.branch_id=%d';$args[]=$branch;}$sql.=' GROUP BY p.currency';$rows=$wpdb->get_results($wpdb->prepare($sql,$args),ARRAY_A);$values=array('USD'=>array('product_lines'=>0,'total_quantity'=>0,'stock_value'=>0),'CDF'=>array('product_lines'=>0,'total_quantity'=>0,'stock_value'=>0));foreach($rows as $row){$cur=$row['currency'];if(isset($values[$cur])){$values[$cur]=array('product_lines'=>(int)$row['product_lines'],'total_quantity'=>(float)$row['total_quantity'],'stock_value'=>(float)$row['stock_value']);}}return array('success'=>true,'branch_id'=>$branch?:null,'valuation_method'=>'quantity × current product purchase_price','currencies'=>$values,'note'=>'Valorisation indicative au coût d’achat actuellement enregistré sur la fiche produit, pas au coût historique moyen.');
 }
}
